insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_74_v1'
from (values
('127.510.d.1.A',3,'Communication is the exchange of information, while the sounds a person produces with the mouth to form words are called:','["speech", "hearing", "grammar", "print"]'::jsonb,0,'Speech is sound production.','original'),
('127.510.d.1.A',4,'The system of rules and symbols used to share meaning, whether spoken, written, or signed, is called:','["breathing", "language", "vision", "posture"]'::jsonb,1,'Language is a rule system.','original'),
('127.510.d.1.B',3,'The vocal folds sit inside the voicebox, which is also called the:','["trachea", "esophagus", "larynx", "pharynx"]'::jsonb,2,'Larynx houses the vocal folds.','original'),
('127.510.d.1.B',4,'The part of the ear that holds the cochlea is the:','["outer ear", "earlobe", "ear canal", "inner ear"]'::jsonb,3,'The cochlea is in the inner ear.','original'),
('127.510.d.1.C',3,'The structures used to shape sounds into speech, such as the tongue, lips, and jaw, are called:','["articulators", "amplifiers", "resonators", "vibrators"]'::jsonb,0,'Articulators shape sound.','original'),
('127.510.d.1.C',4,'The speech system includes breathing, voice production, resonance, and:','["circulation", "articulation", "reproduction", "digestion"]'::jsonb,1,'Four speech subsystems.','original'),
('127.510.d.1.D',3,'Sound waves travel through the ear canal and strike a thin membrane called the:','["larynx", "cochlea", "eardrum", "retina"]'::jsonb,2,'Tympanic membrane vibrates.','original'),
('127.510.d.1.D',4,'The three tiny bones in the middle ear are the malleus, incus, and:','["tibia", "femur", "radius", "stapes"]'::jsonb,3,'Ossicles carry vibrations.','original'),
('127.510.d.1.E',3,'Eye contact, gestures, and facial expressions are forms of:','["nonverbal communication", "verbal fluency", "phonology", "written language"]'::jsonb,0,'Nonverbal cues.','original'),
('127.510.d.1.E',4,'A baby''s cooing and babbling are early steps in healthy verbal:','["silence", "development", "decline", "loss"]'::jsonb,1,'Babbling precedes words.','original'),
('127.510.d.1.F',3,'Before a child can talk, the child must be able to hear, pay attention, and take turns, which are called communication:','["diagnoses", "penalties", "prerequisites", "symptoms"]'::jsonb,2,'Building blocks come first.','original'),
('127.510.d.1.F',4,'Looking at a caregiver and passing sounds back and forth is an early form of:','["spelling", "writing", "reading", "turn-taking"]'::jsonb,3,'Turn-taking builds conversation.','original'),
('127.510.d.1.G',3,'The study of the sounds of language is called:','["phonology", "pragmatics", "semantics", "syntax"]'::jsonb,0,'Phonology = sound system.','original'),
('127.510.d.1.G',4,'The study of word meaning in language is called:','["audiology", "semantics", "morphology", "phonology"]'::jsonb,1,'Semantics = meaning.','original'),
('127.510.d.1.H',3,'Using language in social situations, such as greeting someone or taking turns in a talk, is called:','["phonetics", "anatomy", "pragmatics", "syntax"]'::jsonb,2,'Pragmatics = social language.','original'),
('127.510.d.1.H',4,'A person''s confidence and emotional state can affect how they communicate, which shows the link between communication and:','["astronomy", "geology", "botany", "psychology"]'::jsonb,3,'Psychological bases.','original'),
('127.510.d.2.A',3,'The theory that children learn language by imitating adults and being rewarded is the behaviorist view, associated with:','["B.F. Skinner", "Lev Vygotsky", "Noam Chomsky", "Jean Piaget"]'::jsonb,0,'Skinner proposed learning by reinforcement.','original'),
('127.510.d.2.A',4,'The theory that humans are born with an inborn ability to learn grammar was proposed by:','["B.F. Skinner", "Noam Chomsky", "Sigmund Freud", "Ivan Pavlov"]'::jsonb,1,'Chomsky''s nativist theory.','original'),
('127.510.d.2.B',3,'A theory that says children simplify adult sounds using natural patterns is called:','["behaviorism", "realism", "natural phonology", "humanism"]'::jsonb,2,'Natural phonology.','original'),
('127.510.d.2.B',4,'Models of speech sound production try to explain how children organize and produce the sounds of their:','["toys", "homework", "pets", "language"]'::jsonb,3,'Speech sound theories.','original'),
('127.510.d.2.C',3,'A child with strong spoken language skills is often better prepared to learn to:','["read", "drive", "vote", "swim"]'::jsonb,0,'Language supports literacy.','original'),
('127.510.d.2.C',4,'Difficulty with speech sounds in preschool can later affect the ability to connect sounds with letters, which is called:','["history", "phonics", "geometry", "chemistry"]'::jsonb,1,'Sound-letter links.','original'),
('127.510.d.3.A',3,'The study of how speech sounds are produced by the mouth and throat is called articulatory:','["chemistry", "grammar", "phonetics", "geometry"]'::jsonb,2,'Phonetics.','original'),
('127.510.d.3.A',4,'A sound made with both lips, such as /p/ or /b/, is called:','["dental", "velar", "glottal", "bilabial"]'::jsonb,3,'Bilabial = two lips.','original'),
('127.510.d.3.B',3,'Hearing sounds clearly in early childhood is the foundation for learning to produce:','["speech sounds", "math facts", "colors", "dance steps"]'::jsonb,0,'Auditory feedback shapes speech.','original'),
('127.510.d.3.B',4,'A child with a hearing loss may have trouble with speech because the child cannot clearly hear the sounds to:','["weigh", "imitate", "draw", "measure"]'::jsonb,1,'Hearing guides imitation.','original'),
('127.510.d.3.C',3,'Infants make crying and cooing sounds and later babble, which are early stages of:','["hearing loss", "reading", "vocal development", "handwriting"]'::jsonb,2,'Prespeech development.','original'),
('127.510.d.3.C',4,'Repeating syllables like ''bababa'' is called:','["echolalia only", "stuttering", "jargon", "canonical babbling"]'::jsonb,3,'Babbling stage.','original'),
('127.510.d.3.D',3,'Vowels are important in early speech because they carry much of the sound of a:','["word", "map", "coin", "ruler"]'::jsonb,0,'Vowels are the sound core.','original'),
('127.510.d.3.D',4,'Young children usually produce vowels accurately before they produce most:','["pictures", "consonants", "numbers", "gestures"]'::jsonb,1,'Vowels come first.','original'),
('127.510.d.3.E',3,'A vowel that glides from one position to another, such as in the word ''boy,'' is a:','["fricative", "plosive", "diphthong", "nasal"]'::jsonb,2,'Diphthongs move.','original'),
('127.510.d.3.E',4,'Vowels can be described by tongue height, tongue position, and lip:','["weight", "price", "color", "rounding"]'::jsonb,3,'Vowel features.','original'),
('127.510.d.3.F',3,'The set of consonant sounds a child can produce is the child''s consonant:','["inventory", "menu", "budget", "calendar"]'::jsonb,0,'Inventory = sounds a child can make.','original'),
('127.510.d.3.F',4,'Sounds like /m/, /n/, /p/, /b/, and /h/ are usually among the first consonants children:','["forget", "acquire", "lose", "avoid"]'::jsonb,1,'Early sounds.','original'),
('127.510.d.3.G',3,'Consonants are described by place, manner, and:','["color", "volume only", "voicing", "spelling"]'::jsonb,2,'Place-manner-voicing.','original'),
('127.510.d.3.G',4,'The sound /s/ is a fricative because the air is forced through a narrow:','["gap in a book", "wall", "bone", "opening"]'::jsonb,3,'Fricative = friction.','original'),
('127.510.d.3.H',3,'As children develop, they begin combining sounds into syllables and then into:','["words", "colors", "numbers", "songs only"]'::jsonb,0,'Sound sequencing.','original'),
('127.510.d.3.H',4,'Replacing a hard sound with an easier one, such as saying ''wabbit'' for ''rabbit,'' is a normal speech:','["habit of adults", "process", "injury", "disease"]'::jsonb,1,'Phonological process.','original'),
('127.510.d.3.I',3,'A child who speaks Spanish at home may use sound patterns that differ from English, which reflects the influence of the:','["calendar", "weather", "heritage language", "school bus"]'::jsonb,2,'Native language influence.','original'),
('127.510.d.3.I',4,'Speech differences caused by a home language are considered a language difference, not a speech:','["talent", "award", "advantage", "disorder"]'::jsonb,3,'Difference is not disorder.','original'),
('127.510.d.4.A',3,'The components of language include phonology, morphology, syntax, semantics, and:','["pragmatics", "botany", "chemistry", "geometry"]'::jsonb,0,'Five parts of language.','original'),
('127.510.d.4.A',4,'The rules for putting words in order to form sentences are called:','["prosody", "syntax", "semantics", "phonology"]'::jsonb,1,'Syntax = word order.','original'),
('127.510.d.4.B',3,'The words a person knows and uses make up the person''s:','["schedule", "diet", "vocabulary", "posture"]'::jsonb,2,'Vocabulary.','original'),
('127.510.d.4.B',4,'The smallest unit of meaning in a language, such as the prefix ''un-'', is a:','["letter", "syllable", "phoneme", "morpheme"]'::jsonb,3,'Morphemes carry meaning.','original'),
('127.510.d.4.C',3,'Paying attention to a speaker and understanding simple words are skills a child needs before talking, called language:','["prerequisites", "symptoms", "penalties", "results"]'::jsonb,0,'Prerequisite skills.','original'),
('127.510.d.4.C',4,'Pointing to show an adult something is an early skill called joint:','["breath", "attention", "recess", "fluency"]'::jsonb,1,'Joint attention.','original'),
('127.510.d.4.D',3,'A child whose language skills are developing slowly but in the usual order has a language:','["difference", "habit", "delay", "preference"]'::jsonb,2,'Delay.','original'),
('127.510.d.4.D',4,'A language pattern that differs because of a family''s dialect or culture, with no problem in learning, is a language:','["deficit", "disease", "disorder", "difference"]'::jsonb,3,'Difference.','original'),
('127.510.d.4.E',3,'Most children say their first words at around:','["12 months", "8 years", "5 years", "2 months"]'::jsonb,0,'First words near age 1.','original'),
('127.510.d.4.E',4,'By about age 2, most children begin combining two words, such as ''more milk,'' which is called a:','["story", "two-word phrase", "paragraph", "poem"]'::jsonb,1,'Two-word combinations.','original'),
('127.510.d.4.F',3,'By kindergarten, children typically use complete sentences and understand many more:','["recipes", "maps", "words", "coins"]'::jsonb,2,'Kindergarten language.','original'),
('127.510.d.4.F',4,'In elementary school, children learn to use language for reading, writing, and telling:','["jokes only", "numbers only", "secrets only", "narratives"]'::jsonb,3,'Narratives develop.','original'),
('127.510.d.4.G',3,'During adolescence, language use grows to include more abstract words, slang, and understanding of:','["figurative language", "baby talk", "lullabies", "nursery rhymes"]'::jsonb,0,'Teen language.','original'),
('127.510.d.4.G',4,'A teen using different language with friends than with teachers shows the ability to switch:','["schedules", "registers", "hairstyles", "desks"]'::jsonb,1,'Register shift.','original'),
('127.510.d.4.H',3,'Different cultural backgrounds can influence how children learn to tell stories and take turns in:','["swimming", "gymnastics", "conversation", "sleeping"]'::jsonb,2,'Cultural differences.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_74_v1'
from (values
('127.510.d.4.H',4,'A clinician evaluating a bilingual child should compare the child''s skills with those of other children from a similar:','["shoe size", "hair color", "height", "language background"]'::jsonb,3,'Fair comparison.','original'),
('127.510.d.5.A',3,'Smooth, easy flow of speech is called verbal:','["fluency", "delay", "stuttering", "pitch"]'::jsonb,0,'Fluency.','original'),
('127.510.d.5.A',4,'Repeating sounds, syllables, or words, or blocking on a sound, are called:','["phrases", "disfluencies", "vowels", "dialects"]'::jsonb,1,'Disfluencies.','original'),
('127.510.d.5.B',3,'A child who repeats whole words or phrases such as ''I want, I want'' is showing a typical disfluency type called:','["prolongation", "blocking", "repetition", "silence"]'::jsonb,2,'Normal disfluency.','original'),
('127.510.d.5.B',4,'Many children go through a period of increased disfluency at about age 2 to 5 while their language is:','["fixed", "shrinking", "absent", "growing quickly"]'::jsonb,3,'Developmental disfluency.','original'),
('127.510.d.5.C',3,'Children learn to put sounds together and then to build sentences, a process called speech and language:','["development", "loss", "decay", "failure"]'::jsonb,0,'Skills develop.','original'),
('127.510.d.5.C',4,'A child''s speech becomes easier for strangers to understand as the child''s sound system:','["shrinks", "matures", "vanishes", "freezes"]'::jsonb,1,'Intelligibility improves.','original'),
('127.510.d.5.D',3,'Feeling nervous or talking very fast can make speech less:','["long", "loud", "fluent", "clear to see"]'::jsonb,2,'Variables affect fluency.','original'),
('127.510.d.5.D',4,'Stress, speaking rate, and sentence length are variables that may affect verbal:','["vision", "height", "taste", "fluency"]'::jsonb,3,'Fluency variables.','original'),
('127.510.d.5.E',3,'To measure the fluency of an English language learner, a clinician must consider the speaker''s:','["language experience", "favorite food", "clothing", "height"]'::jsonb,0,'ELL fluency.','original'),
('127.510.d.5.E',4,'A bilingual child''s disfluencies may differ in each language because of different levels of:','["weight", "proficiency", "age at birth", "hobbies"]'::jsonb,1,'Proficiency affects fluency.','original'),
('127.510.d.6.A',3,'Voice is produced when air from the lungs makes the vocal folds:','["freeze", "turn white", "vibrate", "dry out"]'::jsonb,2,'Vocal fold vibration.','original'),
('127.510.d.6.A',4,'The highness or lowness of a voice is its:','["volume", "rate", "rhythm", "pitch"]'::jsonb,3,'Pitch.','original'),
('127.510.d.6.B',3,'A healthy voice has good quality, appropriate pitch, and appropriate:','["loudness", "color", "weight", "height"]'::jsonb,0,'Healthy voice features.','original'),
('127.510.d.6.B',4,'The way the sound from the vocal folds is shaped by the throat, mouth, and nose is called:','["rhythm", "resonance", "pitch", "tempo"]'::jsonb,1,'Resonance.','original'),
('127.510.d.6.C',3,'Yelling and overusing the voice can cause growths on the vocal folds called:','["blisters", "freckles", "nodules", "cavities"]'::jsonb,2,'Vocal nodules.','original'),
('127.510.d.6.C',4,'Reflux, smoking, and dehydration are all causes of changes in voice:','["spelling", "length", "color", "quality"]'::jsonb,3,'Voice variation causes.','original'),
('127.510.d.6.D',3,'During puberty, a boy''s voice becomes lower as the larynx:','["grows larger", "shrinks", "moves away", "stops working"]'::jsonb,0,'Pubertal change.','original'),
('127.510.d.6.D',4,'In older adults, the voice may become weaker or more breathy because the vocal folds become less:','["wet", "firm", "long", "blue"]'::jsonb,1,'Aging voice.','original'),
('127.510.d.6.E',3,'Dry air, loud noise, and pollution are examples of environmental variables that can strain the:','["knees", "eyes", "voice", "feet"]'::jsonb,2,'Environment affects voice.','original'),
('127.510.d.6.E',4,'Teachers and singers who talk loudly all day are at higher risk for voice:','["promotions", "awards", "lessons", "problems"]'::jsonb,3,'Vocal demands.','original'),
('127.510.d.6.F',3,'A speech-language pathologist must have a state license and usually a master''s degree, which defines the practice and allowable:','["services", "hairstyles", "menus", "vacations"]'::jsonb,0,'Scope of practice.','original'),
('127.510.d.6.F',4,'A speech-language pathologist may work with people of all ages in schools, hospitals, and:','["stadiums", "clinics", "airports", "farms only"]'::jsonb,1,'Work settings.','original'),
('127.510.d.6.G',3,'Keeping a client''s information private is part of the ethical duty of:','["advertising", "fashion", "confidentiality", "speed"]'::jsonb,2,'Confidentiality.','original'),
('127.510.d.6.G',4,'A speech-language pathologist should provide only the services that he or she is qualified, meaning working within the limits of:','["budget", "rumors", "luck", "competence"]'::jsonb,3,'Competence.','original'),
('127.510.d.7.A',3,'A child who says a word that others can understand, such as ''ba'' for ''ball,'' is usually about:','["12 to 18 months old", "15 years old", "5 to 6 years old", "10 years old"]'::jsonb,0,'Early word milestones.','original'),
('127.510.d.7.A',4,'Children with typical development usually ask ''what'' and ''where'' questions by about age:','["5 months", "2 to 3", "12", "8 to 9"]'::jsonb,1,'Question milestones.','original'),
('127.510.d.7.B',3,'Language milestones may be compared with the milestones of motor, social, and thinking:','["sports", "fashion", "development", "cooking"]'::jsonb,2,'Development domains.','original'),
('127.510.d.7.B',4,'Delays in language together with delays in walking or thinking may mean a broader developmental:','["trend", "celebration", "holiday", "concern"]'::jsonb,3,'Related areas.','original'),
('127.510.d.7.C',3,'Language used to chat with friends and family is called basic interpersonal communication, while language used for school learning is:','["academic language", "secret code", "slang only", "baby talk"]'::jsonb,0,'BICS and CALP.','original'),
('127.510.d.7.C',4,'It usually takes English language learners longer to develop the language needed for school than for:','["sleeping", "everyday conversation", "sports only", "playing alone"]'::jsonb,1,'Social language comes first.','original'),
('127.510.d.7.D',3,'Everyday words like ''dog'' and ''happy'' are tier 1 vocabulary, while subject-specific words like ''photosynthesis'' are tier:','["0", "7", "3", "1"]'::jsonb,2,'Tier 3 is technical.','original'),
('127.510.d.7.D',4,'Tier 2 words are general academic words used across subjects, such as:','["dog", "table", "cat", "analyze"]'::jsonb,3,'Tier 2 examples.','original'),
('127.510.d.7.E',3,'The ability to tell a story with a beginning, middle, and end shows the development of:','["narrative language", "hearing", "balance", "grip"]'::jsonb,0,'Narrative development.','original'),
('127.510.d.7.E',4,'Written narratives usually develop after:','["birth", "oral narratives", "walking", "reading never"]'::jsonb,1,'Oral comes first.','original'),
('127.510.d.7.F',3,'Skills such as greeting people, staying on topic, and taking turns are part of:','["hearing tests", "voice quality", "pragmatic language", "motor skills"]'::jsonb,2,'Pragmatics.','original'),
('127.510.d.7.F',4,'A child who stands too close and talks about only one topic may have a pragmatic language:','["habit of sleeping", "advantage", "award", "difficulty"]'::jsonb,3,'Pragmatic problems.','original'),
('127.510.d.7.G',3,'Skills that come before reading and writing, such as recognizing letters and rhymes, make up emergent:','["literacy", "athletics", "geography", "numeracy"]'::jsonb,0,'Emergent literacy.','original'),
('127.510.d.7.G',4,'Knowing that spoken words can be broken into separate sounds, a skill that helps with rhyming and reading, is called phonological:','["delay", "awareness", "loss", "blockage"]'::jsonb,1,'Phonological awareness.','original'),
('127.510.d.8.A',3,'A speech-language pathologist helps decide whether a child''s communication is healthy or shows a:','["holiday", "vacation", "disorder", "birthday"]'::jsonb,2,'SLP role.','original'),
('127.510.d.8.A',4,'An SLP can diagnose communication disorders, but cannot diagnose a:','["language disorder", "speech sound disorder", "fluency disorder", "hearing loss medically"]'::jsonb,3,'Scope boundary.','original'),
('127.510.d.8.B',3,'A quick check to decide whether a child needs a full evaluation is called a:','["screening", "discharge", "diagnosis", "treatment"]'::jsonb,0,'Screening.','original'),
('127.510.d.8.B',4,'A screening that shows a possible problem leads to a referral for a full:','["vacation", "evaluation", "party", "contest"]'::jsonb,1,'Screen then evaluate.','original'),
('127.510.d.8.C',3,'A full assessment that measures speech, language, and related skills is a(n):','["screening", "lesson", "evaluation", "recess"]'::jsonb,2,'Evaluation.','original'),
('127.510.d.8.C',4,'Evaluations often include standardized tests, observation, and a case:','["song", "menu", "budget", "history"]'::jsonb,3,'Evaluation components.','original'),
('127.510.d.8.D',3,'In Response to Intervention, students receive more support as they move through increasing:','["tiers", "pets", "vacations", "grades only"]'::jsonb,0,'RtI tiers.','original'),
('127.510.d.8.D',4,'RtI helps schools tell whether a child''s difficulty is due to a disability or to a lack of:','["age", "adequate instruction", "height", "money"]'::jsonb,1,'RtI purpose.','original'),
('127.510.d.8.E',3,'When an SLP finds a problem outside the SLP''s scope, the SLP makes a:','["recipe", "menu", "referral", "joke"]'::jsonb,2,'Referral.','original'),
('127.510.d.8.E',4,'An SLP shares evaluation results with a family and explains them in a process called:','["advertising", "coding", "grading", "counseling"]'::jsonb,3,'Counseling families.','original'),
('127.510.d.9.A',3,'When talking with a client, an SLP should use language that fits the client''s age and:','["understanding", "mood only", "pay", "height"]'::jsonb,0,'Appropriate language.','original'),
('127.510.d.9.A',4,'Making eye contact, listening, and using a calm voice are examples of appropriate communication when working with:','["machines", "clients", "furniture", "tools only"]'::jsonb,1,'Client interaction.','original'),
('127.510.d.9.B',3,'Nodding, smiling, and facing the speaker are examples of:','["syntax", "phonetics", "nonverbal techniques", "verbal fluency"]'::jsonb,2,'Nonverbal skills.','original'),
('127.510.d.9.B',4,'Repeating back what a client has said to show understanding is called:','["assuming", "interrupting", "ignoring", "paraphrasing"]'::jsonb,3,'Paraphrasing.','original'),
('127.510.d.9.C',3,'A device that speaks words when a user presses a symbol is an example of augmentative and alternative communication, called:','["AAC", "MRI", "AED", "EKG"]'::jsonb,0,'AAC.','original'),
('127.510.d.9.C',4,'A tablet app that lets a nonspeaking child choose pictures to make requests is a form of:','["medication", "assistive technology", "surgery", "x-ray"]'::jsonb,1,'Assistive tech.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
