('127.511.d.5.A',4,'A clinician must not call a dialect difference a disorder because dialects are:','["errors", "defects", "diseases", "rule-governed"]'::jsonb,3,'Dialects.','original'),
('127.511.d.5.B',3,'In a simulated interview with a child''s parent, the clinician should ask about the child''s:','["developmental history", "hair length", "shoe size", "favorite color"]'::jsonb,0,'Case history.','original'),
