('127.511.d.6.C',4,'A fluency screening listens for repetitions, prolongations, and:','["colors", "blocks", "maps", "songs"]'::jsonb,1,'Fluency screening.','original'),
('127.511.d.6.D',3,'A developmental screening checks several areas, including speech, language, and:','["address", "income", "motor skills", "hair color"]'::jsonb,2,'Developmental screening.','original'),
