('127.511.d.7.D',4,'Clinical experience helps a clinician apply research findings to an:','["poster", "individual client", "machine", "empty room"]'::jsonb,1,'Clinical judgment.','original'),
('127.511.d.7.E',3,'A project in which a clinician tests a new approach in his or her own practice and records the results is called action:','["fiction", "comedy", "research", "drama"]'::jsonb,2,'Action research.','original'),
