('127.554.d.6.D',4,'Samples in a portfolio should show a student''s best and most typical:','["pets", "work", "hair", "clothes"]'::jsonb,1,'Representative samples.','original'),
('127.555.d.1.A',3,'A nurse needs to give 2 tablets that each contain 250 mg. The total dose in milligrams is:','["252 mg", "1000 mg", "500 mg", "125 mg"]'::jsonb,2,'2 x 250 = 500.','original'),
('127.555.d.1.A',4,'An order is for 750 mg and the tablets are 250 mg each. The number of tablets to give is:','["2", "5", "4", "3"]'::jsonb,3,'750 / 250 = 3.','original'),
('127.555.d.1.B',3,'The medical term meaning high blood pressure is:','["hypertension", "bradycardia", "hypotension", "tachycardia"]'::jsonb,0,'Hypertension.','original'),
